_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[0],[5]]},{"data":{"id":"u03_l03_q014","unit_id":"u03","lesson_id":"u03_l03","difficulty":"hard","type":"multiple_choice","prompt":"كيف يربط الدرس مكان عدة المطلقة رجعيا بإمكان الإصلاح؟","topic":"أحكام العدة والإرث والخطبة","payload":{"options":[{"id":"o1","text":"لأن الرجعة لا تجوز أثناء العدة"},{"id":"o2","text":"لأن الطلاق الرجعي أنهى كل صلة نهائيا"},{"id":"o3","text":"لأن المكان يسقط نفقتها"},{"id":"o4","text":"بقاؤها في عصمته وبيت الزوجية أدعى لرجوع الحياة الأسرية"}]},"answer":{"option_id":"o4"},"explanation":"يعلل النص بقاءها بأنها لا تزال في عصمته وإمكان إرجاعها.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[0],[5]]},{"data":{"id":"u03_l03_q013","unit_id":"u03","lesson_id":"u03_l03","difficulty":"easy","type":"multiple_choice","prompt":"أين تعتد المطلقة طلاقا رجعيا؟","topic":"أحكام العدة والإرث والخطبة","payload":{"options":[{"id":"o1","text":"في بيت الزوجية"},{"id":"o2","text":"خارج بيت الزوجية حتما"},{"id":"o3","text":"في مكان يختاره الجيران"},{"id":"o4","text":"لا يحدد الدرس مكانا"}]},"answer":{"option_id":"o1"},"explanation":"ينص الدرس على وجوب اعتدادها في بيت الزوجية.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[0]]},{"data":{"id":"u03_l03_q016","unit_id":"u03","lesson_id":"u03_l03","difficulty":"medium","type":"multiple_choice","prompt":"ما حكم التوارث إذا توفي أحد الزوجين أثناء عدة طلاق رجعي؟","topic":"أحكام العدة والإرث والخطبة","payload":{"options":[{"id":"o1","text":"يقتصر على من طلب الرجعة"},{"id":"o2","text":"يتوقف على مهر جديد"},{"id":"o3","text":"ينقطع بمجرد التلفظ بالطلاق"},{"id":"o4","text":"يثبت بينهما"}]},"answer":{"option_id":"o4"},"explanation":"نص الدرس على ثبوت الإرث أثناء عدة الطلاق الرجعي.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[0]]},{"data":{"id":"u03_l03_q017","unit_id":"u03","lesson_id":"u03_l03","difficulty":"hard","type":"multiple_choice","prompt":"لم لا يتوارث الزوجان أثناء عدة الطلاق البائن بحسب الدرس؟","topic":"أحكام العدة والإرث والخطبة","payload":{"options":[{"id":"o1","text":"لأن كل عدة تسقط الإرث"},{"id":"o2","text":"لأن الدخول وحده يمنع الإرث"},{"id":"o3","text":"لانتهاء العلاقة الزوجية بينهما"},{"id":"o4","text":"لأن العدة لم تبدأ"}]},"answer":{"option_id":"o3"},"explanation":"علل الكتاب عدم التوارث بانتهاء العلاقة الزوجية في البائن.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[0]]},{"data":{"id":"u03_l03_q020","unit_id":"u03","lesson_id":"u03_l03","difficulty":"medium","type":"matching","prompt":"صل العبارة بنوعها في مثال الخطبة.","topic":"أحكام العدة والإرث والخطبة","payload":{"left":[{"id":"l1","text":"مثلك يرغب في الزواج بها"},{"id":"l2","text":"أرغب في الزواج بك بعد انتهاء العدة"}],"right":[{"id":"r2","text":"تصريح"},{"id":"r1","text":"تعريض"}]},"answer":{"pairs":[{"left_id":"l1","right_id":"r1"},{"left_id":"l2","right_id":"r2"}]},"explanation":"هاتان العبارتان مثالان في تعريف التعريض والتصريح في الهامش.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[1],[8],[12]]},{"data":{"id":"u03_l03_q030","unit_id":"u03","lesson_id":"u03_l03","difficulty":"hard","type":"matching","prompt":"صل المقطع القرآني بالحالة التي استشهد بها جدول العدة له.","topic":"الاستدلال بالنص","payload":{"left":[{"id":"l1","text":"فما لكم عليهن من عدة تعتدونها"},{"id":"l2","text":"وأولات الأحمال أجلهن أن يضعن حملهن"},{"id":"l3","text":"يتربصن بأنفسهن أربعة أشهر وعشرا"}],"right":[{"id":"r2","text":"عدة الحامل"},{"id":"r3","text":"عدة غير الحامل المتوفى عنها زوجها"},{"id":"r1","text":"الطلاق قبل الدخول"}]},"answer":{"pairs":[{"left_id":"l1","right_id":"r1"},{"left_id":"l2","right_id":"r2"},{"left_id":"l3","right_id":"r3"}]},"explanation":"تستدل الصفحة بآية الأحزاب على عدم العدة قبل الدخول في الطلاق، وبآية الطلاق على انتهاء عدة الحامل بالوضع، وبآية البقرة على عدة الوفاة لغير الحامل.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[109],"pdf_pages":[109]}},"uses":[[1],[8],[12]]},{"data":{"id":"u03_l03_q032","unit_id":"u03","lesson_id":"u03_l03","difficulty":"hard","type":"matching","prompt":"صل موضوع الحكم بالسؤال الذي يجب بحثه فيه، حتى لا تختلط أحكام العدة.","topic":"المقارنة وتحليل الأدلة والتطبيق المركب","payload":{"left":[{"id":"l1","text":"مدة الانتظار قبل الزواج"},{"id":"l2","text":"التوارث أثناء العدة"},{"id":"l3","text":"المبيت أثناء حداد الوفاة"}],"right":[{"id":"r1","text":"ما سبب الفرقة وما حالة المرأة؟"},{"id":"r3","text":"هل توجد حاجة أو حالة عدم أمان يذكرها النص؟"},{"id":"r2","text":"هل بقيت رابطة الزوجية في الصورة المذكورة؟"}]},"answer":{"pairs":[{"left_id":"l1","right_id":"r1"},{"left_id":"l2","right_id":"r2"},{"left_id":"l3","right_id":"r3"}]},"explanation":"يفصل السؤال بين المدة والرابطة ومكان المبيت؛ لكل موضوع معطياته في الدرس.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110,111],"pdf_pages":[110,111]}},"uses":[[1],[8],[12]]},{"data":{"id":"u03_l03_q072","unit_id":"u03","lesson_id":"u03_l03","difficulty":"hard","type":"matching","prompt":"طابق المفاهيم الآتية بدلالاتها الدقيقة: بيت المطلقة رجعيا، التوارث في الرجعي، عدم التوارث في البائن، منع خطبة المعتدة من طلاق","topic":"المطابقة الدقيقة بين مفاهيم متقاربة","payload":{"left":[{"id":"l1","text":"بيت المطلقة رجعيا"},{"id":"l2","text":"التوارث في الرجعي"},{"id":"l3","text":"عدم التوارث في البائن"},{"id":"l4","text":"منع خطبة المعتدة من طلاق"}],"right":[{"id":"r1","text":"تعتد في بيت الزوجية لأن الرجعة ممكنة"},{"id":"r4","text":"تحرم خطبتها أثناء عدة الطلاق بأنواعه"},{"id":"r3","text":"لا إرث في عدة الطلاق البائن بسبب انتهاء الزوجية"},{"id":"r2","text":"يثبت إرث الزوجين إذا توفي أحدهما خلال العدة"}]},"answer":{"pairs":[{"left_id":"l1","right_id":"r1"},{"left_id":"l2","right_id":"r2"},{"left_id":"l3","right_id":"r3"},{"left_id":"l4","right_id":"r4"}]},"explanation":"المطابقة المعتمدة: بيت المطلقة رجعيا: تعتد في بيت الزوجية لأن الرجعة ممكنة؛ التوارث في الرجعي: يثبت إرث الزوجين إذا توفي أحدهما خلال العدة؛ عدم التوارث في البائن: لا إرث في عدة الطلاق البائن بسبب انتهاء الزوجية؛ منع خطبة المعتدة من طلاق: تحرم خطبتها أثناء عدة الطلاق بأنواعه.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[110],"pdf_pages":[110]}},"uses":[[1],[8],[12]]},{"data":{"id":"u03_l03_q023","unit_id":"u03","lesson_id":"u03_l03","difficulty":"easy","type":"true_false","prompt":"اشترط الكتاب لبس السواد في حداد الزوجة.","topic":"الحداد","payload":{},"answer":{"value":false},"explanation":"صرح بأنه لا يشترط لون معين في الحداد.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[111],"pdf_pages":[111]}},"uses":[[4]]}]$educational_content$::jsonb) item
